import { useMemo, useState, useEffect, useRef } from "react";
import { useLocation } from "react-router-dom";
import vintedGroups from "../data/vintedCategories";
import { loadInventory, saveInventory } from "../data/inventoryStore";
import "../styles/inventory.css";

/* ================= HELPERS ================= */

function nextStatus(status) {
  if (status === "Bought") return "Listed";
  if (status === "Listed") return "Sold";
  return "Bought";
}

function ensureId(item) {
  if (item?.id) return item;
  const id =
    (typeof crypto !== "undefined" && crypto.randomUUID && crypto.randomUUID()) ||
    `id_${Date.now()}_${Math.random().toString(16).slice(2)}`;
  return { ...item, id };
}

/* ================= CONSTANTS ================= */

const EMPTY_FORM = {
  id: "",
  name: "",
  brand: "",
  size: "",
  colour: "",
  purchasePrice: "",
  purchaseDate: "",
  estimatedSale: "",
  soldPrice: "",
  soldDate: "",
  notes: "",
  status: "Bought",
  categoryPath: [],
  finalCategory: "",
};

const BRANDS = [
  "Ralph Lauren",
  "The North Face",
  "Nike",
  "Adidas",
  "Stone Island",
  "Carhartt",
  "Patagonia",
  "Supreme",
  "Lacoste",
];

const SIZES = ["XS", "S", "M", "L", "XL"];

const COLOURS = [
  { name: "Black", value: "black" },
  { name: "Navy", value: "navy" },
  { name: "White", value: "white" },
  { name: "Red", value: "red" },
  { name: "Green", value: "green" },
  { name: "Pink", value: "pink" },
  { name: "Grey", value: "grey" },
  { name: "Beige", value: "beige" },
];

/* ================= INVENTORY ================= */

export default function Inventory() {
  const location = useLocation();
  const focusId = location.state?.focusId || null;
  const itemRefs = useRef({});
function handleSave() {
  const buy = Number(form.purchasePrice);
  const sold = Number(form.soldPrice);

  if (!String(form.name || "").trim() || buy <= 0) {
    alert("Item name and valid purchase price required.");
    return;
  }

  if (form.status === "Sold" && sold <= 0) {
    alert("Sold price required when status is Sold.");
    return;
  }

  const withId = ensureId(form);

  const itemData = {
    ...withId,
    finalCategory:
      withId.finalCategory ||
      (Array.isArray(withId.categoryPath)
        ? withId.categoryPath[withId.categoryPath.length - 1]
        : "") ||
      "",
  };

  setItems((prev) => {
    const copy = [...prev];
    if (editingIndex !== null) copy[editingIndex] = itemData;
    else copy.push(itemData);
    return copy;
  });

  setForm(EMPTY_FORM);
  setEditingIndex(null);
  setShowModal(false);
}

  const [items, setItems] = useState(() => {
    const raw = loadInventory();
    const arr = Array.isArray(raw) ? raw : [];
    return arr.map(ensureId);
  });

  const [showModal, setShowModal] = useState(false);
  const [quickViewItem, setQuickViewItem] = useState(null);
  const [editingIndex, setEditingIndex] = useState(null);
  const [form, setForm] = useState(EMPTY_FORM);
  const [search, setSearch] = useState("");

  /* ================= PERSIST ================= */

  useEffect(() => {
    saveInventory(items);
  }, [items]);

  /* ================= AI FOCUS / SCROLL ================= */

  useEffect(() => {
    if (!focusId) return;

    const target = itemRefs.current[focusId];
    if (!target) return;

    target.scrollIntoView({ behavior: "smooth", block: "center" });

    target.style.boxShadow =
      "0 0 0 2px rgba(255,60,60,.7), 0 0 28px rgba(255,60,60,.45)";

    const t = setTimeout(() => {
      target.style.boxShadow = "none";
    }, 2500);

    return () => clearTimeout(t);
  }, [focusId]);

  const update = (k, v) => setForm((p) => ({ ...p, [k]: v }));

  /* ================= SEARCH ================= */

  const visible = useMemo(() => {
    const q = search.trim().toLowerCase();
    const base = items.map((item, idx) => ({ item, idx }));

    if (!q) return base;

    return base.filter(({ item }) => {
      const name = String(item.name || "").toLowerCase();
      const brand = String(item.brand || "").toLowerCase();
      const finalCategory = String(item.finalCategory || "").toLowerCase();
      const path = Array.isArray(item.categoryPath)
        ? item.categoryPath.join(" ").toLowerCase()
        : "";

      return (
        name.includes(q) ||
        brand.includes(q) ||
        finalCategory.includes(q) ||
        path.includes(q)
      );
    });
  }, [items, search]);

  /* ================= SUMMARY ================= */

  const summary = useMemo(() => {
    const n = (v) => Number(v) || 0;
    const list = visible.map((x) => x.item);

    return {
      inventory: list
        .filter((i) => i.status !== "Sold")
        .reduce((s, i) => s + n(i.purchasePrice), 0),
      estProfit: list
        .filter((i) => i.status !== "Sold")
        .reduce(
          (s, i) => s + Math.max(n(i.estimatedSale) - n(i.purchasePrice), 0),
          0
        ),
      sold: list
        .filter((i) => i.status === "Sold")
        .reduce((s, i) => s + n(i.soldPrice), 0),
    };
  }, [visible]);

  /* ================= RENDER (TOP) ================= */

  return (
    <div className="inventory-page">
      <h1 className="inventory-title">📦 Inventory</h1>

      {/* SUMMARY CARDS */} 
      <div className="inventory-summary">
        <SummaryCard title="Inventory Value" value={`£${summary.inventory.toFixed(2)}`} emoji="💼" />
        <SummaryCard title="Est Profit (Unsold)" value={`£${summary.estProfit.toFixed(2)}`} emoji="📈" />
        <SummaryCard title="Total Sold" value={`£${summary.sold.toFixed(2)}`} emoji="💸" />
      </div>

      {/* ACTION BAR */}
      <div className="inventory-actions">
        <input
          className="inventory-search"
          placeholder="Search items, brands, categories…"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />

        <button
          className="btn-red"
          onClick={() => {
            setForm(EMPTY_FORM);
            setEditingIndex(null);
            setShowModal(true);
          }}
        >
          ➕ Add Item
        </button>
      </div>

      {/* GRID HEADER (STICKY) */}
      <div className="inventory-grid-header">
        <span>Item</span>
        <span>Brand</span>
        <span>Size</span>
        <span>Colour</span>
        <span>Bought</span>
        <span>Sold</span>
        <span>Status</span>
        <span>Actions</span>
      </div>
      {/* INVENTORY ROWS */}
      {visible.map(({ item, idx }) => (
        <div
          key={item.id}
          ref={(el) => (itemRefs.current[item.id] = el)}
          className="inventory-row"
        >
          {/* ITEM */}
          <div className="inv-name">
            <strong>{item.name}</strong>
            {item.finalCategory && (
              <div className="inv-sub">{item.finalCategory}</div>
            )}
            {Array.isArray(item.categoryPath) && item.categoryPath.length > 0 && (
              <div className="inv-sub">
                📁 {item.categoryPath.join(" / ")}
              </div>
            )}
          </div>

          {/* BRAND */}
          <div>{item.brand || "—"}</div>

          {/* SIZE */}
          <div>{item.size || "—"}</div>

          {/* COLOUR */}
          <div>
            {item.colour ? (
              <span
                className="colour-dot"
                style={{ background: item.colour }}
              />
            ) : (
              "—"
            )}
          </div>

          {/* PURCHASE */}
          <div>£{item.purchasePrice}</div>

          {/* SOLD */}
          <div>{item.soldPrice ? `£${item.soldPrice}` : "—"}</div>

          {/* STATUS */}
          <div
            className={`inv-status ${item.status.toLowerCase()}`}
            onClick={(e) => {
              e.stopPropagation();
              const next = nextStatus(item.status);

              if (next === "Sold" && !item.soldPrice) {
                setForm({ ...item, status: "Sold" });
                setEditingIndex(idx);
                setShowModal(true);
                return;
              }

              setItems((p) =>
                p.map((x, i) =>
                  i === idx ? { ...x, status: next } : x
                )
              );
            }}
          >
            {item.status}
          </div>

          {/* ACTIONS */}
          <div className="inv-actions">
            {/* EDIT */}
            <button
              title="Edit"
              onClick={(e) => {
                e.stopPropagation();
                setForm({ ...item });
                setEditingIndex(idx);
                setShowModal(true);
              }}
            >
              ✏️
            </button>

            {/* DELETE */}
            <button
              title="Delete"
              onClick={(e) => {
                e.stopPropagation();
                setItems((p) => p.filter((_, i) => i !== idx));
              }}
            >
              🗑️
            </button>

            {/* DUPLICATE */}
            <button
              title="Duplicate"
              onClick={(e) => {
                e.stopPropagation();
                setItems((p) => [
                  ...p,
                  ensureId({
                    ...item,
                    status: "Bought",
                    soldPrice: "",
                    soldDate: "",
                  }),
                ]);
              }}
            >
              📄
            </button>

            {/* QUICK VIEW */}
            <button
              title="Quick View"
              onClick={(e) => {
                e.stopPropagation();
                setQuickViewItem(item);
              }}
            >
              👁️
            </button>
          </div>
        </div>
      ))}

      {/* ADD / EDIT MODAL */}
      {showModal && (
        <AddItemModal
          form={form}
          update={update}
          onSave={handleSave}
          onClose={() => setShowModal(false)}
        />
      )}

      {/* QUICK VIEW MODAL */}
      {quickViewItem && (
        <div className="inventory-modal-backdrop">
          <div className="inventory-modal">
            <h2>{quickViewItem.name}</h2>

            <p><b>Brand:</b> {quickViewItem.brand || "—"}</p>
            <p><b>Category:</b> {quickViewItem.finalCategory || "—"}</p>
            <p><b>Status:</b> {quickViewItem.status}</p>
            <p><b>Purchase:</b> £{quickViewItem.purchasePrice}</p>

            {quickViewItem.estimatedSale && (
              <p><b>Estimated:</b> £{quickViewItem.estimatedSale}</p>
            )}

            {quickViewItem.soldPrice && (
              <p><b>Sold:</b> £{quickViewItem.soldPrice}</p>
            )}

            <button
              className="btn-ghost"
              style={{ marginTop: 16, width: "100%" }}
              onClick={() => setQuickViewItem(null)}
            >
              Close
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

/* ================= SMALL COMPONENTS ================= */

function SummaryCard({ title, value, emoji }) {
  return (
    <div className="inventory-summary-card">
      <span>{emoji} {title}</span>
      <strong>{value}</strong>
    </div>
  );
}

/* ================= ADD ITEM MODAL ================= */

function AddItemModal({ form, update, onSave, onClose }) {
  const s = {
    width: "100%",
    padding: 12,
    borderRadius: 12,
    background: "var(--bg-input)",
    border: "1px solid var(--border-soft)",
    color: "#fff",
    marginTop: 10,
  };

  return (
    <div className="inventory-modal-backdrop">
      <div className="inventory-modal">
        <h2>{form.id ? "Edit Item" : "Add Item"}</h2>

        <VintedCategoryPicker
          groups={vintedGroups}
          value={form.categoryPath}
          onChange={(path) => {
            update("categoryPath", path);
            update("finalCategory", path[path.length - 1] || "");
          }}
        />

        <input
          placeholder="Item name *"
          value={form.name}
          onChange={(e) => update("name", e.target.value)}
          style={s}
        />

        <input
          list="brands"
          placeholder="Brand"
          value={form.brand}
          onChange={(e) => update("brand", e.target.value)}
          style={s}
        />

        <datalist id="brands">
          {BRANDS.map((b) => (
            <option key={b} value={b} />
          ))}
        </datalist>

        <select
          value={form.size}
          onChange={(e) => update("size", e.target.value)}
          style={s}
        >
          <option value="">📏 Size</option>
          {SIZES.map((x) => (
            <option key={x}>{x}</option>
          ))}
        </select>

        <select
          value={form.colour}
          onChange={(e) => update("colour", e.target.value)}
          style={s}
        >
          <option value="">🎨 Colour</option>
          {COLOURS.map((c) => (
            <option key={c.value} value={c.value}>
              {c.name}
            </option>
          ))}
        </select>

        <input
          type="number"
          placeholder="Purchase price *"
          value={form.purchasePrice}
          onChange={(e) => update("purchasePrice", e.target.value)}
          style={s}
        />

        <input
          type="date"
          value={form.purchaseDate}
          onChange={(e) => update("purchaseDate", e.target.value)}
          style={s}
        />

        <input
          type="number"
          placeholder="Estimated sale price"
          value={form.estimatedSale}
          onChange={(e) => update("estimatedSale", e.target.value)}
          style={s}
        />

        <select
          value={form.status}
          onChange={(e) => update("status", e.target.value)}
          style={s}
        >
          <option value="Bought">🛒 Bought</option>
          <option value="Listed">📦 Listed</option>
          <option value="Sold">✅ Sold</option>
        </select>

        {form.status === "Sold" && (
          <>
            <input
              type="number"
              placeholder="Sold price *"
              value={form.soldPrice}
              onChange={(e) => update("soldPrice", e.target.value)}
              style={s}
            />
            <input
              type="date"
              value={form.soldDate || ""}
              onChange={(e) => update("soldDate", e.target.value)}
              style={s}
            />
          </>
        )}

        <textarea
          placeholder="Notes"
          value={form.notes}
          onChange={(e) => update("notes", e.target.value)}
          style={{ ...s, height: 90 }}
        />

        <button
          onClick={onSave}
          className="btn-red"
          style={{ width: "100%", marginTop: 16 }}
        >
          💾 Save Item
        </button>

        <button
          onClick={onClose}
          className="btn-ghost"
          style={{ width: "100%", marginTop: 8 }}
        >
          Cancel
        </button>
      </div>
    </div>
  );
}

/* ================= CATEGORY PICKER ================= */

function VintedCategoryPicker({ groups, value, onChange }) {
  const [path, setPath] = useState(value || []);
  const [node, setNode] = useState({ children: groups });

  useEffect(() => {
    let cur = { children: groups };
    for (const p of path) cur = cur.children?.[p] || cur;
    setNode(cur);
  }, [path, groups]);

  return (
    <div>
      <div
        className="glass"
        style={{
          padding: "6px 10px",
          borderRadius: 10,
          marginBottom: 6,
          fontSize: 12,
          display: "flex",
          flexWrap: "wrap",
          gap: 6,
        }}
      >
        {path.length === 0
          ? "Select category…"
          : path.map((p, i) => (
              <span
                key={i}
                onClick={() => {
                  const np = path.slice(0, i + 1);
                  setPath(np);
                  onChange(np);
                }}
                style={{ cursor: "pointer", textDecoration: "underline" }}
              >
                {p}
                {i < path.length - 1 && " › "}
              </span>
            ))}
      </div>

      <div
        className="glass"
        style={{
          maxHeight: 140,
          overflowY: "auto",
          padding: 6,
          borderRadius: 10,
        }}
      >
        {Object.keys(node.children || {}).map((k) => (
          <div
            key={k}
            onClick={() => {
              const np = [...path, k];
              setPath(np);
              onChange(np);
            }}
            style={{ padding: "4px 6px", cursor: "pointer", fontSize: 12 }}
          >
            📁 {k}
          </div>
        ))}
      </div>
    </div>
  );
}
